import Path from "./path.js";
import { isGenerator } from "./utils/generator.js";
import { concurrent } from "./utils/concurrent.js";
import { mergeData } from "./utils/merge-data.js";
import { getBasename, getPageUrl } from "./utils/page-url.js";
import { getPageDate } from "./utils/page-date.js";
import { log } from "./utils/log.js";
import { getInclude } from "./utils/includes.js";
/**
 * The renderer is responsible for rendering the site pages
 * in the right order and using the right template engine.
 */
export default class Renderer {
    /** The filesystem instance used to read the layouts */
    fs;
    /** To convert the urls to pretty /example.html => /example/ */
    prettyUrls;
    /** All preprocessors */
    preprocessors;
    /** Available file formats */
    formats;
    /** The registered helpers */
    helpers = new Map();
    constructor(options) {
        this.prettyUrls = options.prettyUrls;
        this.preprocessors = options.preprocessors;
        this.formats = options.formats;
        this.fs = options.fs;
    }
    /** Register a new helper used by the template engines */
    addHelper(name, fn, options) {
        this.helpers.set(name, [fn, options]);
        for (const format of this.formats.entries.values()) {
            format.engines?.forEach((engine) => engine.addHelper(name, fn, options));
        }
        return this;
    }
    /** Render the provided pages */
    async renderPages(from, to, debugBar) {
        const renderedPages = [];
        for (const group of this.#groupPages(from)) {
            const pages = [];
            const generators = [];
            // Split regular pages and generators
            for (const page of group) {
                if (isGenerator(page.data.content)) {
                    generators.push(page);
                    continue;
                }
                pages.push(page);
            }
            // Preprocess the pages and add them to site.pages
            await this.preprocessors.run(pages, debugBar);
            to.push(...pages);
            debugBar?.startMeasure("generators");
            const generatedPages = [];
            for (const page of generators) {
                const data = { ...page.data };
                const { content } = data;
                delete data.content;
                const generator = await this.render(content, data, page.src.path + page.src.ext);
                let index = 0;
                const basePath = Path.dirname(page.data.url);
                for await (const data of generator) {
                    if (data.url === false) {
                        continue;
                    }
                    if (!data.content) {
                        data.content = undefined;
                    }
                    const newPage = page.duplicate(index++, mergeData(page.data, data));
                    let base = basePath;
                    if (!data.url && data.basename !== undefined) {
                        // @ts-ignore: The url is added later
                        delete newPage.data.url;
                        base = Path.dirname(page.outputPath);
                    }
                    const url = getPageUrl(newPage, this.prettyUrls, base);
                    if (!url) {
                        continue;
                    }
                    newPage.data.url = url;
                    newPage.data.basename = getBasename(url);
                    newPage.data.date = getPageDate(newPage);
                    // Prevent running the layout if the page is not HTML
                    if (!data.layout && !newPage.isHTML) {
                        delete newPage.data.layout;
                    }
                    generatedPages.push(newPage);
                }
            }
            debugBar?.endMeasure("generators", `[Generators] Created ${generatedPages.length} pages`);
            // Preprocess the generators and add them to site.pages
            await this.preprocessors.run(generatedPages, debugBar);
            to.push(...generatedPages);
            // Render the pages content
            debugBar?.startMeasure("render");
            await concurrent(pages.concat(generatedPages), async (page) => {
                try {
                    const content = await this.#renderPage(page);
                    // Save the children to render the layout later
                    if (page.data.layout || page.isHTML) {
                        page.data.children = content;
                        renderedPages.push(page);
                    }
                    else {
                        page.content = content;
                    }
                }
                catch (cause) {
                    log.error(`[rendering] Error rendering the page ${page.sourcePath}: ${cause.message}`);
                }
            });
            debugBar?.endMeasure("render", `[Rendering] Content of ${renderedPages.length} pages`);
        }
        // Render the pages layouts at the end
        debugBar?.startMeasure("render-layouts");
        await concurrent(renderedPages, async (page) => {
            try {
                page.content = await this.#renderLayout(page, page.data.children);
            }
            catch (cause) {
                log.error(`[rendering] Error rendering the layout of the page ${page.sourcePath}: ${cause.message}`);
            }
        });
        debugBar?.endMeasure("render-layouts", `[Rendering] Layouts of ${renderedPages.length} pages`);
    }
    /** Render a template */
    async render(content, data, filename, isLayout = false) {
        /** site.page({ url: "foo", content: (data) => "..." }) */
        if (filename === "" && !data.templateEngine && typeof content === "function") {
            data.templateEngine = "js";
        }
        const engines = this.#getEngine(filename, data, isLayout);
        if (engines) {
            for (const engine of engines) {
                content = await engine.render(content, data, filename);
            }
        }
        return content;
    }
    /** Group the pages by renderOrder */
    #groupPages(pages) {
        const renderOrder = {};
        for (const page of pages) {
            const order = page.data.renderOrder || 0;
            renderOrder[order] = renderOrder[order] || [];
            renderOrder[order].push(page);
        }
        return Object.keys(renderOrder)
            .sort()
            .map((order) => renderOrder[order]);
    }
    /** Render a page */
    async #renderPage(page) {
        const data = { ...page.data };
        const { content } = data;
        delete data.content;
        return await this.render(content, data, page.src.path + page.src.ext);
    }
    /** Render the page layout */
    async #renderLayout(page, content) {
        let data = { ...page.data };
        let fromDir = Path.dirname(page.src.path + page.src.ext);
        let layout = data.layout;
        // Render the layouts recursively
        while (layout) {
            const format = this.formats.search(layout);
            if (!format || !format.loader) {
                throw new Error(`The layout format "${layout}" doesn't exist`);
            }
            const layoutEntry = getInclude(fromDir, layout, this.fs);
            if (!layoutEntry) {
                throw new Error(`The layout file "${layout}" from the dir "${fromDir}" doesn't exist`);
            }
            const layoutData = await layoutEntry.getContent(format.loader);
            delete data.layout;
            delete data.templateEngine;
            data = mergeData(layoutData, data, { content });
            content = await this.render(layoutData.content, data, layoutEntry.path, true);
            layout = layoutData.layout;
            fromDir = Path.dirname(layoutEntry.path);
        }
        return content;
    }
    /** Get the engines assigned to an extension or configured in the data */
    #getEngine(path, data, isLayout) {
        let { templateEngine } = data;
        if (templateEngine) {
            templateEngine = Array.isArray(templateEngine) ? templateEngine : templateEngine.split(",");
            return templateEngine.reduce((engines, name) => {
                const format = this.formats.get(`.${name.trim()}`);
                if (format?.engines) {
                    return engines.concat(format.engines);
                }
                throw new Error(`The template engine "${name}" doesn't exist`);
            }, []);
        }
        const format = this.formats.search(path);
        if (isLayout || format?.isPage) {
            return format?.engines;
        }
    }
}
